using UnityEngine;
using UnityEngine.UI;
public sealed class HudGraphic:MaskableGraphic {
 public enum Style{Button,Page,Core,Up,Down}public Style style;bool focused,paused;VertexHelper mesh;float phase,nextFrame,mic;public int MicrophoneLevel;public float AnimationPhase{get{return phase;}}
 void OnApplicationPause(bool value){paused=value;}
 void Update(){if(style==Style.Button)return;if(paused||!isActiveAndEnabled||(style==Style.Button&&!focused)||Time.unscaledTime<nextFrame)return;nextFrame=Time.unscaledTime+1f/24f;phase+=1f/24f;mic=Mathf.Lerp(mic,Mathf.Clamp01(MicrophoneLevel/100f),.25f);SetVerticesDirty();}
 public void Focus(bool value){if(focused==value)return;focused=value;SetVerticesDirty();}
 public static HudGraphic Create(Transform parent,Vector2 position,Vector2 size,Style kind){var g=new GameObject("HUD light strokes",typeof(RectTransform),typeof(HudGraphic));g.transform.SetParent(parent,false);var rt=g.GetComponent<RectTransform>();rt.anchoredPosition=position;rt.sizeDelta=size;var hud=g.GetComponent<HudGraphic>();hud.style=kind;hud.raycastTarget=false;return hud;}
 void Stroke(Vector2 a,Vector2 b,float width,float alpha){var n=(b-a).normalized;var p=new Vector2(-n.y,n.x)*width*.5f;var tint=new Color(.12f,.74f,1f,Mathf.Clamp01(alpha*(focused?1.5f:1)));int index=mesh.currentVertCount;mesh.AddVert(a-p,tint,Vector2.zero);mesh.AddVert(a+p,tint,Vector2.zero);mesh.AddVert(b+p,tint,Vector2.zero);mesh.AddVert(b-p,tint,Vector2.zero);mesh.AddTriangle(index,index+1,index+2);mesh.AddTriangle(index+2,index+3,index);}
 void Line(Vector2 a,Vector2 b,float alpha=.5f){Stroke(a,b,9,alpha*.07f);Stroke(a,b,3,alpha*.19f);Stroke(a,b,1,alpha);}
 void Arc(Vector2 center,float radius,float from,float to,float alpha){int count=Mathf.CeilToInt(Mathf.Abs(to-from)/6);var last=center+new Vector2(Mathf.Cos(from*Mathf.Deg2Rad),Mathf.Sin(from*Mathf.Deg2Rad))*radius;for(int i=1;i<=count;i++){float a=Mathf.Lerp(from,to,i/(float)count)*Mathf.Deg2Rad;var next=center+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*radius;Line(last,next,alpha);last=next;}}
 protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();mesh=vh;float x=rectTransform.rect.width*.5f,y=rectTransform.rect.height*.5f;
  if(style==Style.Button){float c=11;Line(new Vector2(-x,-y+c),new Vector2(-x,-y));Line(new Vector2(-x,-y),new Vector2(-x+c,-y));Line(new Vector2(x,y-c),new Vector2(x,y));Line(new Vector2(x,y),new Vector2(x-c,y));Line(new Vector2(-x*.55f,-y),new Vector2(x*.55f,-y),.18f);}
  else if(style==Style.Up||style==Style.Down){float d=style==Style.Up?1:-1;for(int i=0;i<2;i++){float y0=(i*12-10)*d;float alpha=.55f+.22f*Mathf.Sin(phase*3-i);Line(new Vector2(-16,y0-8*d),new Vector2(0,y0+5*d),alpha);Line(new Vector2(0,y0+5*d),new Vector2(16,y0-8*d),alpha);}}
  else if(style==Style.Core){float turn=phase*18;float breathe=.5f+.5f*Mathf.Sin(phase*1.7f);Arc(Vector2.zero,98,18+turn,151+turn,.75f);Arc(Vector2.zero,98,198+turn,331+turn,.75f);Arc(Vector2.zero,108,-48-turn*.6f,65-turn*.6f,.4f);Arc(Vector2.zero,108,132-turn*.6f,245-turn*.6f,.4f);for(int i=0;i<48;i++){float a=(i*7.5f+turn*.25f)*Mathf.Deg2Rad;var d=new Vector2(Mathf.Cos(a),Mathf.Sin(a));Line(d*115,d*(i%4==0?123:118),i%4==0?.55f:.2f);}float radius=70+3*breathe;for(int i=0;i<5;i++)Arc(Vector2.zero,radius-i*3,0,360,(.06f+.025f*breathe)*(1-i*.15f));float scan=Mathf.Sin(phase*.8f)*75;float half=Mathf.Sqrt(Mathf.Max(0,80*80-scan*scan));Line(new Vector2(-half,scan),new Vector2(half,scan),.18f+.12f*breathe);for(int i=0;i<15;i++){float height=2+mic*24*(.35f+.65f*Mathf.Abs(Mathf.Sin(i*1.7f+phase*12)));float px=(i-7)*7;Line(new Vector2(px,-30-height),new Vector2(px,-30+height),.5f+mic*.4f);}}
  else{Line(new Vector2(-x+10,y),new Vector2(-x+210,y),.45f);float sweep=Mathf.PingPong(phase*80,Mathf.Max(1,x*2-100))-x;Line(new Vector2(sweep,y),new Vector2(sweep+75,y),.65f);Line(new Vector2(x-210,y),new Vector2(x-10,y),.45f);Line(new Vector2(-x,y-16),new Vector2(-x,y-95),.35f);Line(new Vector2(x,-y+16),new Vector2(x,-y+95),.35f);Arc(new Vector2(-x+55,-y+65),30,30,255,.3f);Arc(new Vector2(x-55,y-65),30,195,420,.3f);}
 }
}
